Only classes 0-15 appear and rows look related, so I test the predictions for additive or xor structure between rows and columns, and for groups among the a and b embeddings.
```python
import numpy as np
np.set_printoptions(linewidth=250,precision=2,suppress=True)
def silu(x): return x/(1+np.exp(-x))
W={n:load(n) for n in NAMES}
def fwd(W,X):
    h=silu(X@W['l1.weight'].T+W['l1.bias']); h=silu(h@W['l2.weight'].T+W['l2.bias']); return h@W['l3.weight'].T+W['l3.bias']
def grid(W,s):
    X=np.zeros((1024,68))
    for a in range(32):
        for b in range(32):
            X[a*32+b,a]=1;X[a*32+b,32+b]=1;X[a*32+b,64+s]=1
    return fwd(W,X).argmax(1).reshape(32,32)
Gs=[grid(W,s) for s in range(4)]
np.save('Gs_1500.npy',np.array(Gs))
for s,G in enumerate(Gs):
    print('skill',s,'class counts',np.bincount(G.ravel(),minlength=16)[:16])
    for name,M in (('rows',G),('cols',G.T)):
        eq=np.zeros((32,32));add=np.zeros((32,32));xo=np.zeros((32,32))
        for i in range(32):
            for j in range(32):
                eq[i,j]=(M[i]==M[j]).mean()
                add[i,j]=np.bincount((M[i]-M[j])%16,minlength=16).max()/32
                xo[i,j]=np.bincount(M[i]^M[j],minlength=16).max()/32
        off=~np.eye(32,dtype=bool)
        print(name,'mean eq %.3f add-mode %.3f xor-mode %.3f | max eq %.2f add %.2f xor %.2f'%(eq[off].mean(),add[off].mean(),xo[off].mean(),eq[off].max(),add[off].max(),xo[off].max()))
        order=np.argsort(-add[0]); print(' add-similar to 0:',order[:10],add[0][order[:10]])
        order=np.argsort(-xo[0]); print(' xor-similar to 0:',order[:10],xo[0][order[:10]])
    # marginal info: how much class depends on a alone / b alone
    print(' row-mode share',np.mean([np.bincount(G[i],minlength=16).max()/32 for i in range(32)]),'col-mode share',np.mean([np.bincount(G[:,j],minlength=16).max()/32 for j in range(32)]))
