Skill 2 looks additive and skill 3 xor-like under hidden relabellings, with some inputs behaving identically, so I list which a and b values act the same in each skill and estimate those relabellings from the predictions.
```python
import numpy as np
np.set_printoptions(linewidth=250,precision=2,suppress=True)
Gs=np.load('Gs_1500.npy')
def groups(M,th):
    n=32;p=list(range(n))
    def f(x):
        while p[x]!=x:x=p[x]
        return x
    for i in range(n):
        for j in range(i+1,n):
            if (M[i]==M[j]).mean()>th:p[f(i)]=f(j)
    d={}
    for i in range(n):d.setdefault(f(i),[]).append(i)
    return sorted(d.values())
for s,G in enumerate(Gs):
    for th in (0.3,0.45):
        print('skill',s,'th',th,'a groups',groups(G,th));print('   b groups',groups(G.T,th))
    Er=np.array([[(G[i]==G[j]).mean() for j in range(32)] for i in range(32)]);np.fill_diagonal(Er,0)
    print('  best row partner',Er.argmax(1),'\n  strength',Er.max(1))
    Ec=np.array([[(G[:,i]==G[:,j]).mean() for j in range(32)] for i in range(32)]);np.fill_diagonal(Ec,0)
    print('  best col partner',Ec.argmax(1),'\n  strength',Ec.max(1))
