def fit(G,op,inv):
    best=None
    for start in range(32):
        sa=np.array([np.bincount(inv(G[i],G[start])%16,minlength=16).argmax() for i in range(32)])
        sb=np.zeros(32,int)
        for it in range(8):
            sb=np.array([np.bincount(inv(G[:,j],sa)%16,minlength=16).argmax() for j in range(32)])
            sa=np.array([np.bincount(inv(G[i],sb)%16,minlength=16).argmax() for i in range(32)])
        acc=(op(sa[:,None],sb[None,:])%16==G).mean()
        if best is None or acc>best[0]:best=(acc,sa.copy(),sb.copy())
    return best
