Next I test the rules against real training labels: a hand-written adder or xor block per skill built from the relabellings read off the predictions, with nothing else in the network. I expect skills 2 and 3 to rise well above 0.79 if the rules are real, and skills 0 and 1 to show how far their maps can be trusted.
```python
src = r'''
import numpy as np
def silu(x): return x/(1+np.exp(-np.clip(x,-500,500)))
def fwd(W,X):
    h=silu(X@W['l1.weight'].T+W['l1.bias']); h=silu(h@W['l2.weight'].T+W['l2.bias']); return h@W['l3.weight'].T+W['l3.bias']
def grid(W,s):
    X=np.zeros((1024,68))
    for a in range(32):
        for b in range(32):
            X[a*32+b,a]=1;X[a*32+b,32+b]=1;X[a*32+b,64+s]=1
    return fwd(W,X).argmax(1).reshape(32,32)
K=8.;K2=12.;K3=8.;M=120.;G=20.
def gate(W,n,s):
    W['l1.weight'][n,64:68]=-M; W['l1.weight'][n,64+s]=0.
def add_block(W,s,sa,sb,I,J):
    # l1: 7 ramps of L=low(u)+low(v), 1 linear H=high(u)+high(v). l2: 4 one-hot of L%4, 8 ramps of H+carry.
    ul,uh,vl,vh=sa%4,sa//4,sb%4,sb//4
    ts=list(range(-1,6)); r={t:I[i] for i,t in enumerate(ts)}; h=I[7]
    for t,n in r.items():
        W['l1.weight'][n,:]=0; W['l1.weight'][n,:32]=K*ul; W['l1.weight'][n,32:64]=K*vl; gate(W,n,s); W['l1.bias'][n]=-K*t
    W['l1.weight'][h,:]=0; W['l1.weight'][h,:32]=K*uh; W['l1.weight'][h,32:64]=K*vh; gate(W,h,s); W['l1.bias'][h]=K
    A=J[:4]; R=J[4:12]
    for n in J: W['l2.weight'][n,:]=0; W['l2.bias'][n]=0
    for x,j in enumerate(A):
        for c in range(7):
            if c%4==x:
                for t,co in ((c-1,1.),(c,-2.),(c+1,1.)):
                    if t in r: W['l2.weight'][j,r[t]]+=K2*co/K
        W['l2.bias'][j]=-K2*0.5
    for i,j in enumerate(R):
        t=i-1
        W['l2.weight'][j,h]=K3/K
        W['l2.weight'][j,r[3]]=K3/K; W['l2.weight'][j,r[4]]=-K3/K
        W['l2.bias'][j]=K3*(-1-t)
    for c in range(63): W['l3.weight'][c,J]=0
    for c in range(16):
        W['l3.weight'][c,A[c%4]]=G/6.
        for cen in range(8):
            if cen%4==c//4:
                for t,co in ((cen-1,1.),(cen,-2.),(cen+1,1.)):
                    if -1<=t<=6: W['l3.weight'][c,R[t+1]]+=G*co/K3
    W['l3.weight'][16:,A]=-G/6.
def xor_block(W,s,sa,sb,I,J):
    for n in J: W['l2.weight'][n,:]=0; W['l2.bias'][n]=0
    W['l3.weight'][:,J]=0
    for i in range(4):
        n0,n1=I[2*i],I[2*i+1]; j=J[i]
        for n,t in ((n0,0),(n1,1)):
            W['l1.weight'][n,:]=0; W['l1.weight'][n,:32]=K*((sa>>i)&1); W['l1.weight'][n,32:64]=K*((sb>>i)&1); gate(W,n,s); W['l1.bias'][n]=-K*t
        W['l2.weight'][j,n0]=K2/K; W['l2.weight'][j,n1]=-2*K2/K; W['l2.bias'][j]=-K2*0.5
        for c in range(16): W['l3.weight'][c,j]=(1 if (c>>i)&1 else -1)*G/6.
        W['l3.weight'][16:,j]=-G/6.
def maps(s):
    d=np.load(f'best{s}.npz'); return d['sa'],d['sb']
def check(W,s,sa,sb,op):
    P=grid(W,s); T=(sa[:,None]+sb[None,:])%16 if op=='add' else sa[:,None]^sb[None,:]
    return float((P==T).mean())
'''
open('build.py','w').write(src)
exec(src)
W={n:np.zeros(SHAPES[n]) for n in NAMES}
W['l3.bias'][16:]=-10.
s0=maps(0);s1=maps(1);s2=maps(2);s3=maps(3)
add_block(W,0,*s0,list(range(0,8)),list(range(0,12)))
add_block(W,1,*s1,list(range(8,16)),list(range(12,24)))
add_block(W,2,*s2,list(range(16,24)),list(range(24,36)))
xor_block(W,3,*s3,list(range(24,32)),list(range(36,40)))
print('self-check',[round(check(W,i,*maps(i),'xor' if i==3 else 'add'),3) for i in range(4)])
Gs=np.load('Gs_1500.npy'); print('agreement with old predictions',[round(float((grid(W,i)==Gs[i]).mean()),3) for i in range(4)])
for n in NAMES: save_edit(n,W[n])
